@import "@fontsource-variable/instrument-sans";

/* Light sibling: the cream band (#f1f0ea) becomes the page, near-black text, a paler cream
   for cards, the same stone grey (#8e9291), olive (#505544) and lime (#dff140). */
:root {
  --background: oklch(0.951 0.008 100);
  --foreground: oklch(0.067 0 0);
  --card: oklch(0.982 0.005 100);
  --card-foreground: oklch(0.067 0 0);
  --popover: oklch(0.982 0.005 100);
  --popover-foreground: oklch(0.067 0 0);
  --primary: oklch(0.91 0.19 115);
  --primary-foreground: oklch(0.067 0 0);
  --secondary: oklch(0.658 0.005 180);
  --secondary-foreground: oklch(0.067 0 0);
  --muted: oklch(0.885 0.008 100);
  --muted-foreground: oklch(0.47 0.006 180);
  --accent: oklch(0.43 0.025 120);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.577 0.215 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.067 0 0 / 30%);
  --input: oklch(0.067 0 0 / 30%);
  --ring: oklch(0.43 0.025 120);
  --highlight: oklch(0.6 0.15 120);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.91 0.19 115);
  --chart-1: oklch(0.43 0.025 120);
  --chart-2: oklch(0.658 0.005 180);
  --chart-3: oklch(0.6 0.15 120);
  --chart-4: oklch(0.067 0 0);
  --chart-5: oklch(0.885 0.008 100);
  --sidebar: oklch(0.982 0.005 100);
  --sidebar-foreground: oklch(0.067 0 0);
  --sidebar-primary: oklch(0.43 0.025 120);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.885 0.008 100);
  --sidebar-accent-foreground: oklch(0.067 0 0);
  --sidebar-border: oklch(0.067 0 0 / 30%);
  --sidebar-ring: oklch(0.43 0.025 120);

  --typeface-body: "Instrument Sans Variable", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --typeface-display: "Instrument Sans Variable", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 2px;
  --page-width: 120rem;
  --page-gutter: clamp(1.25rem, 2.2vw, 2rem);
  --section-y: 5rem;
}

/* Faithful mode: near-black page (#010101), white text, a dark placeholder surface, the
   stone-grey band (#8e9291) with black text, cream (#f1f0ea) news band, olive (#505544)
   editorial band, grey labels, lime (#dff140) for focus and glow. */
.dark {
  --background: oklch(0.067 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.951 0.008 100);
  --card-foreground: oklch(0.067 0 0);
  --popover: oklch(0.067 0 0);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.91 0.19 115);
  --primary-foreground: oklch(0.067 0 0);
  --secondary: oklch(0.658 0.005 180);
  --secondary-foreground: oklch(0.067 0 0);
  --muted: oklch(0.235 0.004 150);
  --muted-foreground: oklch(0.68 0.005 180);
  --accent: oklch(0.43 0.025 120);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.65 0.2 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 22%);
  --input: oklch(1 0 0 / 30%);
  --ring: oklch(0.91 0.19 115);
  --highlight: oklch(0.91 0.19 115);
  --highlight-foreground: oklch(0.067 0 0);
  --glow: oklch(0.91 0.19 115);
  --chart-1: oklch(0.91 0.19 115);
  --chart-2: oklch(0.658 0.005 180);
  --chart-3: oklch(0.43 0.025 120);
  --chart-4: oklch(0.951 0.008 100);
  --chart-5: oklch(0.68 0.005 180);
  --sidebar: oklch(0.12 0 0);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.91 0.19 115);
  --sidebar-primary-foreground: oklch(0.067 0 0);
  --sidebar-accent: oklch(0.235 0.004 150);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 22%);
  --sidebar-ring: oklch(0.91 0.19 115);
}
